-- ========================================================
-- TGAT2 Simulator - Seed 80 Questions into Supabase
-- Copy and paste this script into your Supabase SQL Editor and click RUN
-- ========================================================

-- 1. Ensure 'image' column exists in 'questions' table
ALTER TABLE questions ADD COLUMN IF NOT EXISTS image TEXT;

-- 2. Configure Row Level Security (RLS) to allow public reading & management
ALTER TABLE questions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public select on questions" ON questions;
CREATE POLICY "Allow public select on questions" ON questions FOR SELECT TO public USING (true);
DROP POLICY IF EXISTS "Allow public insert on questions" ON questions;
CREATE POLICY "Allow public insert on questions" ON questions FOR INSERT TO public WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public update on questions" ON questions;
CREATE POLICY "Allow public update on questions" ON questions FOR UPDATE TO public USING (true);

-- 3. Clear existing questions and insert all 80 real questions
DELETE FROM questions;

INSERT INTO questions (id, skill, skill_label, topic, content, choices, correct_answer, explanation, image, svg_illustration) VALUES
(1, 'verbal', 'ความสามารถทางภาษา', 'การสื่อความหมายและความกำกวม', 'ข้อใดมีความหมายไม่กำกวม', '[{"id":1,"text":"สายการบินนี้ราคาไม่แพง"},{"id":2,"text":"ช่างทำผมให้เธออายุน้อย"},{"id":3,"text":"เขาสัญญาว่าวันนี้จะกลับมา"},{"id":4,"text":"ฉันไปพบแพทย์ตามเวลานัด"},{"id":5,"text":"พี่ไปเที่ยวกับเพื่อนต่างจังหวัด"}]'::jsonb, 4, '{"summary":"ประโยค \"ฉันไปพบแพทย์ตามเวลานัด\" มีความหมายชัดเจนและตรงประเด็น ไม่สามารถตีความได้หลายแง่มุม","steps":["ตัวเลือก 1: อาจกำกวมว่าตั๋วเครื่องบินราคาไม่แพง หรือราคาค่าบริการทั้งหมด","ตัวเลือก 2: กำกวมว่า \"ช่าง\" อายุน้อย หรือ \"เธอ\" อายุน้อย","ตัวเลือก 3: กำกวมว่า \"สัญญาวันนี้\" ว่าจะกลับมา หรือสัญญาไว้ก่อนแล้วว่าจะ \"กลับมาวันนี้\"","ตัวเลือก 4: ชัดเจน สื่อสารตรงประเด็น ไม่มีความหมายซ้อน","ตัวเลือก 5: กำกวมว่า เพื่อนเป็นคนต่างจังหวัด หรือพี่กับเพื่อนไปเที่ยวที่ต่างจังหวัด"],"tip":"สังเกตประโยคที่ส่วนขยายอาจโยงไปขยายคำหน้าหรือคำหลังได้ จะเป็นประโยคกำกวม"}'::jsonb, NULL, NULL),
(2, 'verbal', 'ความสามารถทางภาษา', 'การใช้ภาษาและการสื่อความหมาย', 'ข้อใดใช้ภาษาสื่อความหมายได้ถูกต้อง', '[{"id":1,"text":"เขาคือผู้นำในอุดมการณ์ของประชาชน"},{"id":2,"text":"ยานี้ใช้รักษาโรคได้อย่างมีประสิทธิภาพ"},{"id":3,"text":"เครื่องยนต์ของรถรุ่นใหม่มีสมรรถภาพสูง"},{"id":4,"text":"ครูตั้งปฏิญาณว่าจะทำหน้าที่ในการสอนให้ดีที่สุด"},{"id":5,"text":"เขามีเอกสิทธิ์มากกว่าคนอื่นในการรับมรดกจากครอบครัว"}]'::jsonb, 2, '{"summary":"คำว่า \"ประสิทธิภาพ\" ใช้กับยา เครื่องมือ หรือกระบวนการทำงานได้อย่างถูกต้องตามบริบท","steps":["ตัวเลือก 1: ควรใช้ \"ผู้นำในอุดมคติ\"","ตัวเลือก 2: \"ยานี้ใช้รักษาโรคได้อย่างมีประสิทธิภาพ\" ใช้คำถูกต้องตามความหมายและบริบท","ตัวเลือก 3: เครื่องยนต์ ควรใช้ \"สมรรถนะ\"","ตัวเลือก 4: ควรใช้ \"ตั้งปณิธาน\" หรือ \"กล่าวคำปฏิญาณ\"","ตัวเลือก 5: มรดก เป็นเรื่องสิทธิ ไม่ใช่ \"เอกสิทธิ์\" (เอกสิทธิ์มักใช้กับสิทธิพิเศษทางการทูตหรือกฎหมาย)"],"tip":"จำแนกคำที่มักใช้สับสน เช่น สมรรถนะ (เครื่องยนต์) vs สมรรถภาพ (ร่างกาย)"}'::jsonb, NULL, NULL),
(3, 'verbal', 'ความสามารถทางภาษา', 'ความหมายตรงและความหมายโดยนัย', 'ข้อใดมีความหมายทั้งโดยตรงและโดยนัยทุกคำ', '[{"id":1,"text":"ถือดี ถือศีล ถือตัว"},{"id":2,"text":"น้ำใจ น้ำคำ น้ำมือ"},{"id":3,"text":"ลูกไม้ ลูกมือ ลูกหม้อ"},{"id":4,"text":"หน้าใหญ่ หน้าซื่อ หน้าเลือด"},{"id":5,"text":"ไม้นวม ไม้บรรทัด ไม้กระดาน"}]'::jsonb, 5, '{"summary":"ไม้นวม (ไม้ตีระนาด / การประนีประนอม), ไม้บรรทัด (อุปกรณ์วัด / คนที่เที่ยงตรงมาก), ไม้กระดาน (แผ่นไม้ / รูปร่างที่แบนเรียบ) ทั้ง 3 คำมีความหมายทั้งตรงและนัยครบทุกคำ","steps":["ไม้นวม: ตรง = ไม้ตีระนาดที่พันผ้าให้นุ่ม / นัย = การใช้วิธีนุ่มนวล ประนีประนอม","ไม้บรรทัด: ตรง = เครื่องเขียนวัดความยาว / นัย = คนที่ตรงตามระเบียบเป๊ะ ไม่ยืดหยุ่น","ไม้กระดาน: ตรง = แผ่นไม้ / นัย = รูปร่างหน้าอกแบนราบ","ตัวเลือกอื่นมีบางคำที่มีเฉพาะความหมายโดยนัยหรือความหมายตรงอย่างเดียว"],"tip":"ตรวจสอบว่าแต่ละคำสามารถนำมาใช้แทนวัตถุสิ่งของจริง ๆ ได้หรือไม่"}'::jsonb, NULL, NULL),
(4, 'verbal', 'ความสามารถทางภาษา', 'การตีความหมายของคำในบริบท', '“ความรู้เชิงทฤษฎี เราควรนำไปประยุกต์ให้เหมาะสมกับบริบท จึงจะเกิดประโยชน์อย่างแท้จริง”

คำว่า “ประยุกต์” สื่อความหมายตรงกับข้อใด', '[{"id":1,"text":"ปรับแก้"},{"id":2,"text":"ปรับใช้"},{"id":3,"text":"ปรับปรุง"},{"id":4,"text":"ปรับแต่ง"},{"id":5,"text":"ปรับเปลี่ยน"}]'::jsonb, 2, '{"summary":"คำว่า \"ประยุกต์\" หมายถึง นำความรู้หรือหลักการไปปรับใช้ให้เหมาะสมกับการปฏิบัติงานจริง","steps":["ประยุกต์ = นำหลักวิชาการมาปรับใช้ในทางปฏิบัติ","ตัวเลือกที่ตรงที่สุดคือ 2. ปรับใช้"],"tip":"การประยุกต์ (Applied) คือการนำสิ่งที่มีอยู่ไปปรับใช้กับสถานการณ์จริง"}'::jsonb, NULL, NULL),
(5, 'verbal', 'ความสามารถทางภาษา', 'ระดับความหมายของคำ (ความหมายกว้าง-แคบ)', 'คำว่า “ผลิตภัณฑ์” ในข้อใดมีความหมายกว้างที่สุด', '[{"id":1,"text":"ผลิตภัณฑ์ชุมชนของไทยมีคุณภาพดีและราคาถูก"},{"id":2,"text":"รัฐมีนโยบายสำคัญเพื่อการส่งออกสินค้าการเกษตร"},{"id":3,"text":"บรรจุภัณฑ์ที่ใช้วัตถุดิบในชุมชนจะช่วยลดค่าใช้จ่ายได้"},{"id":4,"text":"เราควรส่งเสริมผลิตภัณฑ์ไทยให้มีมาตรฐานสู่ระดับสากล"},{"id":5,"text":"ปัจจุบันตลาดต่างประเทศให้ความสนใจกับหัตถกรรมพื้นบ้านของไทย"}]'::jsonb, 4, '{"summary":"\"ผลิตภัณฑ์ไทย\" ในตัวเลือกที่ 4 ครอบคลุมทั้งสินค้าอุตสาหกรรม การเกษตร หัตถกรรม และบริการทั้งหมดของประเทศ จึงมีความหมายกว้างที่สุด","steps":["ตัวเลือก 1: ผลิตภัณฑ์ชุมชน (แคบกว่า เฉพาะในระดับชุมชน)","ตัวเลือก 2: สินค้าการเกษตร (แคบ เฉพาะภาคเกษตร)","ตัวเลือก 3: บรรจุภัณฑ์ (แคบ เฉพาะหีบห่อ)","ตัวเลือก 4: ผลิตภัณฑ์ไทย (ครอบคลุมทุกสินค้าและบริการของไทยในระดับประเทศสู่สากล)","ตัวเลือก 5: หัตถกรรมพื้นบ้าน (แคบ เฉพาะงานฝีมือพื้นบ้าน)"],"tip":"เปรียบเทียบขอบเขตของสิ่งของที่คำนั้นสื่อถึง คำที่ครอบคลุมประเภทได้มากกว่าจะกว้างกว่า"}'::jsonb, NULL, NULL),
(6, 'verbal', 'ความสามารถทางภาษา', 'ระดับภาษาและภาษาแบบแผน', 'ข้อใดใช้ภาษาเป็นแบบแผน', '[{"id":1,"text":"การรอไม่เป็น จะเพาะความเห็นแก่ตัว"},{"id":2,"text":"การฝึกสมาธิเสริมสร้างนิสัยให้รู้จักการรอ"},{"id":3,"text":"การทำงานใหญ่ ๆ ก็ต้องใช้เวลาจึงต้องรอ"},{"id":4,"text":"การรอนั้นเป็นจุดเริ่มต้นของการยับยั้งชั่งใจ"},{"id":5,"text":"การรู้จักรอเป็นอุปนิสัยที่ดีอย่างหนึ่งของคนเรา"}]'::jsonb, 2, '{"summary":"ตัวเลือก 2 ใช้ถ้อยคำที่เป็นทางการ สละสลวย ถูกไวยากรณ์ และไม่มีคำฟุ่มเฟือยหรือภาษาพูด","steps":["ตัวเลือก 1: มีคำว่า \"เพาะ\" ในความหมายเปรียบเทียบแบบภาษาพูด","ตัวเลือก 2: \"การฝึกสมาธิเสริมสร้างนิสัยให้รู้จักการรอ\" เป็นโครงสร้างประโยคแบบแผนสมบูรณ์","ตัวเลือก 3: มีคำซ้ำ \"ใหญ่ ๆ\" และ \"ก็ต้อง\" ซึ่งเป็นภาษาปาก","ตัวเลือก 4: มีคำว่า \"การรอนั้น\" เป็นภาษาพูดกึ่งทางการ","ตัวเลือก 5: มีคำว่า \"คนเรา\" ซึ่งเป็นภาษาไม่เป็นทางการ"],"tip":"ภาษาแบบแผนจะไม่มีไม้ยมก คำสรรพนามภาษาพูด หรือคำเชื่อมฟุ่มเฟือย"}'::jsonb, NULL, NULL),
(7, 'verbal', 'ความสามารถทางภาษา', 'การเปรียบเทียบระดับและรูปแบบภาษา', 'ข้อใดใช้ภาษาแตกต่างจากข้ออื่น', '[{"id":1,"text":"ถ้าเราทำอะไรเหมือนเดิม สมองเราก็จะเกิดความเคยชิน"},{"id":2,"text":"การทำอะไรที่แตกต่างไป สมองจะโฟกัสไปกับสิ่งใหม่"},{"id":3,"text":"การฝึกให้สมองเกิดการรับรู้บ่อย ๆ สมองก็จะทำงานได้ดีขึ้น"},{"id":4,"text":"สมองก็เหมือน ๆ กับร่างกาย ถ้าไม่ออกกำลัง สมองจะฝ่อเร็วขึ้น"},{"id":5,"text":"การที่สมองถูกกระตุ้นอยู่เสมอ เซลล์สมองจะแข็งแรงทำให้ไม่เฉื่อยชา"}]'::jsonb, 5, '{"summary":"ตัวเลือก 5 เป็นภาษาทางการเชิงวิชาการ (เซลล์สมอง กระตุ้น เฉื่อยชา) ขณะที่ข้ออื่นเป็นภาษากึ่งทางการหรือภาษาปาก (โฟกัส, เหมือน ๆ กับ, ฝ่อ)","steps":["ข้อ 1, 2, 3, 4 มีลักษณะเป็นภาษาพูด/ภาษาปาก (เช่น มีคำทับศัพท์ \"โฟกัส\", คำซ้ำ \"เหมือน ๆ\", ภาษาบรรยายทั่วไป)","ข้อ 5 ใช้ศัพท์ทางการ/วิทยาศาสตร์ \"เซลล์สมอง\" \"ถูกกระตุ้น\" \"เฉื่อยชา\" จัดเป็นภาษาแบบแผนทางวิชาการ"],"tip":"สังเกตการใช้คำศัพท์ทางการ vs คำทับศัพท์หรือคำภาษาปาก"}'::jsonb, NULL, NULL),
(8, 'verbal', 'ความสามารถทางภาษา', 'ภาษาเชิงวิชาการ', 'ข้อใดเป็นภาษาเชิงวิชาการ', '[{"id":1,"text":"ทฤษฎีที่เป็นที่ยอมรับกันคืออุกกาบาตยักษ์โหม่งโลก"},{"id":2,"text":"ด้านที่โลกหันหนีดวงอาทิตย์เป็นช่วงเวลาที่โลกมืดมิด"},{"id":3,"text":"โลกหมุนรอบดวงอาทิตย์โดยวงโคจรมีมุมเอียงเล็กน้อย"},{"id":4,"text":"ราว 3 ล้านปีที่แล้วสภาพอากาศของโลกแปรเปลี่ยนมาก"},{"id":5,"text":"สิ่งแวดล้อมของโลกปัจจุบันทรุดโทรมลงเพราะน้ำมือมนุษย์"}]'::jsonb, 3, '{"summary":"\"โลกหมุนรอบดวงอาทิตย์โดยวงโคจรมีมุมเอียงเล็กน้อย\" บรรยายข้อเท็จจริงทางวิทยาศาสตร์ด้วยภาษาที่เป็นกลางและถูกต้องตามแบบแผนวิชาการ","steps":["ตัวเลือก 1: มีคำว่า \"โหม่งโลก\" ซึ่งเป็นภาษาปาก","ตัวเลือก 2: มีคำว่า \"โลกมืดมิด\" ซึ่งเป็นภาษาพรรณนาวรรณศิลป์","ตัวเลือก 3: ใช้ศัพท์ดาราศาสตร์ที่เป็นแบบแผนทางวิชาการชัดเจน (วงโคจร, มุมเอียง)","ตัวเลือก 4: มีคำว่า \"ราว\" และ \"แปรเปลี่ยนมาก\" ซึ่งไม่ระบุเจาะจงเชิงวิชาการ","ตัวเลือก 5: มีคำว่า \"น้ำมือมนุษย์\" ซึ่งเป็นภาษาภาพพจน์/สำนวน"],"tip":"ภาษาเชิงวิชาการต้องปราศจากคำสแลง ภาษาปาก สำนวน และคำพรรณนาอารมณ์"}'::jsonb, NULL, NULL),
(9, 'verbal', 'ความสามารถทางภาษา', 'การใช้คำบุพบทและถ้อยคำภาษา', 'ข้อใดใช้ถ้อยคำภาษาได้ถูกต้อง', '[{"id":1,"text":"นักเรียนนำเสนอโครงงานกับครูเพื่อส่งเข้าประกวด"},{"id":2,"text":"เด็กที่ติดเกมจะเกี่ยวข้องต่อปัญหาทักษะทางสังคม"},{"id":3,"text":"โรงเรียนมอบทุนการศึกษากับนักเรียนเรียนดีแต่ยากจน"},{"id":4,"text":"ถ้าพ่อแม่เลี้ยงลูกให้อยู่กับทีวีและมือถือจะส่งผลกับสมาธิของเด็ก"},{"id":5,"text":"โครงการพัฒนาทักษะการอ่านให้แก่เด็กจะใช้วิธีฝึกฝนตามขั้นตอน"}]'::jsonb, 5, '{"summary":"การให้หรือมอบสิ่งของจากผู้ใหญ่สู่เด็ก ให้ใช้คำว่า \"ให้แก่\" หรือ \"แก่\" ได้ถูกต้องตามหลักภาษา","steps":["ตัวเลือก 1: ควรใช้ \"นำเสนอโครงงานต่อครู\"","ตัวเลือก 2: ควรใช้ \"สัมพันธ์กับ\" หรือ \"ส่งผลต่อ\"","ตัวเลือก 3: ผู้ใหญ่มอบของให้ผู้น้อย ควรใช้ \"แก่นักเรียน\"","ตัวเลือก 4: ควรใช้ \"ส่งผลต่อสมาธิของเด็ก\"","ตัวเลือก 5: \"ให้แก่เด็ก\" ใช้คำบุพบทถูกต้องตามลำดับอาวุโส"],"tip":"แก่ = ผู้ใหญ่มอบให้ผู้น้อย / แด่ = ผู้น้อยมอบให้ผู้ใหญ่ / ต่อ = ยื่นเสนอต่อผู้มีอำนาจ"}'::jsonb, NULL, NULL),
(10, 'verbal', 'ความสามารถทางภาษา', 'ความเหมาะสมในการเขียนรายงานวิชาการ', 'ข้อใดใช้ภาษาไม่เหมาะสมในการเขียนรายงานวิชาการ', '[{"id":1,"text":"การปลูกต้นไม้ในเมืองจะช่วยดูดซับสารพิษในอากาศได้"},{"id":2,"text":"การแก้ไขปัญหามลพิษต้องบริหารจัดการอย่างเป็นระบบ"},{"id":3,"text":"ปัญหาสุขภาพของคนในสังคมเมืองเกิดจากปัญหาสิ่งแวดล้อมเป็นสำคัญ"},{"id":4,"text":"ฝุ่นละอองขนาดเล็กที่คนเราหายใจเข้าไป ก่อให้เกิดโรคระบบทางเดินหายใจ"},{"id":5,"text":"นักวิชาการแนะว่าให้ออกกำลังกายเป็นประจำ โดยเลือกประเภทได้ตามใจชอบ"}]'::jsonb, 5, '{"summary":"มีคำว่า \"แนะว่า\" และ \"ตามใจชอบ\" ซึ่งเป็นภาษาพูด ไม่เหมาะสมกับรายงานวิชาการ (ควรใช้ \"แนะนำว่า\" และ \"ตามความเหมาะสม\")","steps":["ข้อ 1-4 ใช้ภาษาแบบแผนรัดกุม ถูกต้องตามหลักรายงานวิชาการ","ข้อ 5 มีคำว่า \"แนะว่า\" (ตัดทอนคำ) และ \"ตามใจชอบ\" (ภาษาปากกึ่งทางการ)"],"tip":"รายงานวิชาการต้องใช้คำเต็ม ไม่ตัดทอน และเลี่ยงสำนวนภาษาพูด"}'::jsonb, NULL, NULL),
(11, 'verbal', 'ความสามารถทางภาษา', 'การจับใจความสำคัญและสาระสำคัญ', '“สิ่งที่จะทำให้เราเก่งคือการเรียนรู้ ประกอบด้วยการลงมือทำ เริ่มจากการฟัง การอ่าน แต่ถ้าเราไม่ได้ลงมือทำก็จะไม่ซึมลงไปในความจำระยะยาว การลงมือทำจะทำให้เราเข้าใจอย่างลึกซึ้ง เพราะได้นำความรู้ที่เรียนมาไปใช้ได้ตามสภาพจริง”

จากข้อความนี้นำเสนอสาระใดเป็นสำคัญ', '[{"id":1,"text":"ความรู้"},{"id":2,"text":"ความขยัน"},{"id":3,"text":"ความตั้งใจ"},{"id":4,"text":"ความฉลาด"},{"id":5,"text":"ความสามารถ"}]'::jsonb, 5, '{"summary":"ข้อความเน้นว่าการลงมือทำจะนำความรู้ไปใช้ได้จริงจนเกิดความเชี่ยวชาญ ซึ่งหมายถึง \"ความสามารถ\" ที่แท้จริง","steps":["ประเด็นของข้อความคือ \"สิ่งที่จะทำให้เราเก่ง\" เกิดจากการลงมือทำจนนำไปใช้ได้จริง","การนำความรู้ไปใช้จนเกิดทักษะและความเก่ง ตรงกับคำว่า \"ความสามารถ\""],"tip":"พิจารณาคำสำคัญในประโยคแรก \"สิ่งที่จะทำให้เราเก่ง\" ชี้ถึงทักษะและความสามารถ"}'::jsonb, NULL, NULL),
(12, 'verbal', 'ความสามารถทางภาษา', 'การวิเคราะห์และตีความสาร', '“เราอาจเผลอใช้คำพูดทำร้ายความรู้สึกของผู้อื่น ฉะนั้นเราควรไตร่ตรองก่อนพูด และรับฟังสิ่งที่คนอื่นต้องการ ด้วยความเข้าใจ เพื่อหลีกเลี่ยงความเข้าใจผิดที่อาจทำให้เกิดความรู้สึกที่ไม่ดีต่อกัน”

จากข้อความนี้ไม่เกี่ยวข้องกับเรื่องใด', '[{"id":1,"text":"ค่านิยม"},{"id":2,"text":"ทัศนคติ"},{"id":3,"text":"กาลเทศะ"},{"id":4,"text":"การสื่อสาร"},{"id":5,"text":"ความสัมพันธ์"}]'::jsonb, 1, '{"summary":"ข้อความพูดถึงการพูด (การสื่อสาร), การไตร่ตรองก่อนพูด (กาลเทศะ), ความเข้าใจต่อผู้อื่น (ทัศนคติ), และความรู้สึกต่อกัน (ความสัมพันธ์) แต่ไม่ได้กล่าวถึง \"ค่านิยม\" ของสังคม","steps":["ตัวเลือก 2 ทัศนคติ: เกี่ยวข้องกับการเข้าใจและเปิดใจรับฟังผู้อื่น","ตัวเลือก 3 กาลเทศะ: เกี่ยวกับการไตร่ตรองคำพูดให้เหมาะสม","ตัวเลือก 4 การสื่อสาร: เกี่ยวกับการพูดและการรับฟังตรง ๆ","ตัวเลือก 5 ความสัมพันธ์: เกี่ยวกับการไม่ทำให้เกิดความรู้สึกไม่ดีต่อกัน","ตัวเลือก 1 ค่านิยม: ไม่ได้มีการกล่าวถึงในเนื้อหา"],"tip":"ใช้วิธีจับคู่ตัวเลือกกับใจความย่อยในบทความ ข้อที่ไม่มีคู่คือคำตอบ"}'::jsonb, NULL, NULL),
(13, 'verbal', 'ความสามารถทางภาษา', 'การวิเคราะห์เจตนาและแก่นสาร', '“ทรัพยากรธรรมชาติที่เราใช้อยู่ทุกวันนี้ มันเป็นของลูกหลาน เรายืมลูกหลานมาใช้ เราจึงต้องดูแลให้ดี พอถึงเวลา เราต้องส่งต่อให้ลูกหลาน จึงต้องส่งต่อในสภาพที่ดี”

คำกล่าวนี้ สื่อถึงเรื่องใดเป็นสำคัญ', '[{"id":1,"text":"ความใส่ใจ"},{"id":2,"text":"ความมีวินัย"},{"id":3,"text":"ความผูกพัน"},{"id":4,"text":"ความเอื้อเฟื้อ"},{"id":5,"text":"ความรับผิดชอบ"}]'::jsonb, 5, '{"summary":"การตระหนักว่าทรัพยากรเป็นของคนรุ่นหลังและต้องดูแลส่งต่อในสภาพที่ดี สะท้อนถึง \"ความรับผิดชอบ\" ต่อส่วนรวมและอนาคต","steps":["คำว่า \"ยืมมาใช้... จึงต้องดูแลให้ดี... ต้องส่งต่อในสภาพที่ดี\" แสดงถึงพันธะหน้าที่และความรับผิดชอบ","ตัวเลือกที่ครอบคลุมความหมายนี้ที่สุดคือ 5. ความรับผิดชอบ"],"tip":"การดูแลสิ่งของที่ยืมมาแล้วส่งคืนในสภาพสมบูรณ์คือหัวใจของความรับผิดชอบ"}'::jsonb, NULL, NULL),
(14, 'verbal', 'ความสามารถทางภาษา', 'จุดประสงค์ของผู้เขียน', 'คำชี้แจง: ใช้ข้อความนี้ตอบคำถามข้อ 14 - 15
“เชื่อหรือไม่ว่าบางครั้งคนที่ประสบความสำเร็จระดับโลกไม่ได้เติบโตมาจากคำชม แต่กลับเป็นคำสบประมาท เช่น วอลต์ ดิสนีย์ ที่ต้องออกจากบริษัทเดิมด้วยเหตุผลว่าไม่มีความคิดสร้างสรรค์ แต่เขาสามารถสร้างบริษัทผลิตการ์ตูนและประสบความสำเร็จมาจนถึงทุกวันนี้ คำติชมจึงเป็นเหมือนเหรียญสองด้าน ถ้าได้รับคำชมง่าย ๆ อาจทำให้เราหยุดความคิดเพื่อพัฒนา แต่หากได้รับคำติแล้วนำมาพัฒนา ปรับจุดอ่อน เสริมจุดแข็ง เหมือนการทำตัวเป็นน้ำที่ไม่เต็มแก้วอยู่เสมอ เราก็จะเก่งขึ้นเรื่อย ๆ”

“เชื่อหรือไม่ว่าบางครั้งคนที่ประสบความสำเร็จระดับโลกไม่ได้เติบโตมาจากคำชม แต่กลับเป็นคำสบประมาท” จากข้อความนี้ ผู้เขียนมีวัตถุประสงค์ใด', '[{"id":1,"text":"สั่งสอน"},{"id":2,"text":"ให้ข้อคิด"},{"id":3,"text":"เสนอแนะ"},{"id":4,"text":"ให้กำลังใจ"},{"id":5,"text":"บอกกล่าว"}]'::jsonb, 2, '{"summary":"ผู้เขียนยกประเด็นนี้ขึ้นมาเพื่อให้ผู้อ่านได้คิดทบทวนมุมมองต่อคำสบประมาทว่าสามารถแปรเปลี่ยนเป็นแรงผลักดันได้ จึงเป็นการ \"ให้ข้อคิด\"","steps":["ผู้เขียนไม่ได้ออกคำสั่งว่าต้องทำอะไร จึงไม่ใช่สั่งสอนหรือเสนอแนะ","การชี้ให้เห็นมุมมองใหม่เรื่องคำชมและคำสบประมาท จัดเป็นการให้ข้อคิดในการดำเนินชีวิต"],"tip":"บทความที่ยกตัวอย่างบุคคลระดับโลกเพื่อเปลี่ยนมุมมองความคิด มักมีจุดประสงค์เพื่อ \"ให้ข้อคิด\""}'::jsonb, NULL, NULL),
(15, 'verbal', 'ความสามารถทางภาษา', 'การตีความสำนวนและอุปมาอุปไมย', '“เหมือนการทำตัวเป็นน้ำที่ไม่เต็มแก้วอยู่เสมอ” จากข้อความนี้ไม่เกี่ยวข้องกับข้อใด', '[{"id":1,"text":"ให้รู้จักตนเอง"},{"id":2,"text":"ให้พัฒนาตนเอง"},{"id":3,"text":"ให้ยอมรับสิ่งใหม่"},{"id":4,"text":"ให้คิดหลาย ๆ มุม"},{"id":5,"text":"ให้มั่นใจในตัวเอง"}]'::jsonb, 5, '{"summary":"การเป็นน้ำไม่เต็มแก้วหมายถึงการถ่อมตน เปิดรับความรู้ และไม่คิดว่าตนเองเก่งแล้ว ซึ่งตรงข้ามกับ \"การมั่นใจในตัวเองมากเกินไป\"","steps":["น้ำไม่เต็มแก้ว = พร้อมเรียนรู้สิ่งใหม่ (3), ตระหนักว่ายังขาดความรู้ (1), ปรับปรุงให้ดีขึ้น (2), มองมุมอื่นเพื่อต่อยอด (4)","ตัวเลือกที่ไม่สอดคล้องคือ 5. ให้มั่นใจในตัวเอง"],"tip":"น้ำไม่เต็มแก้ว เน้นการเปิดรับและการเรียนรู้ ไม่ใช่การยึดมั่นในความมั่นใจของตนเอง"}'::jsonb, NULL, NULL),
(16, 'verbal', 'ความสามารถทางภาษา', 'การเติมคำลงในช่องว่าง', 'การเฝ้าระวังผู้ที่มีอาการของโรคทางเดินหายใจต้อง________ให้ชัดเจนว่าเป็นผู้ติดเชื้อหรือไม่และบันทึกไว้เป็น________ในการรักษา', '[{"id":1,"text":"สรุป / สถิติ"},{"id":2,"text":"คัดกรอง / ระบบ"},{"id":3,"text":"สันนิษฐาน / ข้อมูล"},{"id":4,"text":"ระบุ / หมวดหมู่"},{"id":5,"text":"จำแนก / หลักฐาน"}]'::jsonb, 2, '{"summary":"ในทางการแพทย์ การแยกผู้ติดเชื้อเบื้องต้นเรียกว่า \"คัดกรอง\" และการบันทึกอย่างเป็นระเบียบเรียกว่า \"บันทึกไว้เป็นระบบ\"","steps":["ขั้นตอนแรกของการเฝ้าระวังโรคระบาดคือการ \"คัดกรอง\"","การบันทึกสำหรับการรักษาผู้ป่วยต้องทำอย่างมี \"ระบบ\""],"tip":"เลือกคู่คำที่สอดคล้องกับศัพท์ทางการแพทย์และการบริหารจัดการสาธารณสุข"}'::jsonb, NULL, NULL),
(17, 'verbal', 'ความสามารถทางภาษา', 'การเติมคำลงในช่องว่าง', 'ความผิดหวังในอดีตไม่ใช่สิ่งที่จะ________ความผิดพลาดในอนาคต และไม่ใช่สิ่ง________ให้เราเดินไปข้างหน้าได้', '[{"id":1,"text":"ชี้นำ / ยับยั้ง"},{"id":2,"text":"ทำนาย / ปิดกั้น"},{"id":3,"text":"แสดงถึง / ขัดขวาง"},{"id":4,"text":"คาดการณ์ / บั่นทอน"},{"id":5,"text":"กฎเกณฑ์ / เหนี่ยวรั้ง"}]'::jsonb, 2, '{"summary":"ความผิดหวังไม่สามารถ \"ทำนาย\" อนาคตได้ และไม่ควรนำมา \"ปิดกั้น\" การก้าวเดินไปข้างหน้า","steps":["ช่องว่างแรก: อนาคตเป็นสิ่งที่ยังไม่เกิด จึงใช้คำว่า \"ทำนาย\"","ช่องว่างที่สอง: เดินไปข้างหน้า สอดคล้องกับคำว่า \"ปิดกั้น\""],"tip":"พิจารณาความสัมพันธ์ของคู่คำที่ส่งเสริมความหมายเชิงปรัชญาและกำลังใจ"}'::jsonb, NULL, NULL),
(18, 'verbal', 'ความสามารถทางภาษา', 'สำนวนไทยและบริบทการใช้', 'เขาเตรียมงบไว้เพื่อทำธุรกิจ แต่เมื่อเริ่มลงมือทำ กลับต้องจ่าย________ไปเรื่อย ๆ เพื่อให้งานสำเร็จ', '[{"id":1,"text":"เบี้ยประกัน"},{"id":2,"text":"เบี้ยหัวแตก"},{"id":3,"text":"เบี้ยเลี้ยงชีพ"},{"id":4,"text":"เบี้ยบ้ายรายทาง"},{"id":5,"text":"เบี้ยน้อยหอยน้อย"}]'::jsonb, 4, '{"summary":"\"เบี้ยบ้ายรายทาง\" หมายถึง เงินที่ต้องจ่ายปลีกย่อยหรือจ่ายเป็นสินบน/ค่าธรรมเนียมยิบย่อยไปตลอดทางเพื่อให้งานสำเร็จลุล่วง","steps":["เบี้ยหัวแตก: เงินก้อนเล็กก้อนน้อยที่กระจัดกระจาย ใช้ประโยชน์เป็นชิ้นเป็นอันไม่ได้","เบี้ยบ้ายรายทาง: เงินที่ต้องเสียไปเรื่อย ๆ ระหว่างทำกิจการหรือเดินทาง","บริบทระบุว่า \"ต้องจ่ายไปเรื่อย ๆ เพื่อให้งานสำเร็จ\" จึงตรงกับ \"เบี้ยบ้ายรายทาง\""],"tip":"เบี้ยบ้ายรายทาง = เงินที่ต้องจ่ายแทรกซึมตลอดขั้นตอนการทำงาน"}'::jsonb, NULL, NULL),
(19, 'verbal', 'ความสามารถทางภาษา', 'การเลือกใช้คำตามความหมายและบริบท', 'สถานที่แห่งนี้คุณจะได้พบกับความแตกต่างที่เป็น________อันแท้จริงของคนไทยภาคเหนือ เราเชื่อว่าคุณจะหลงรักผู้คนที่นี่', '[{"id":1,"text":"วอแวด"},{"id":2,"text":"อัตลักษณ์"},{"id":3,"text":"วัฒนธรรม"},{"id":4,"text":"จารีตประเพณี"},{"id":5,"text":"ขนบธรรมเนียม"}]'::jsonb, 2, '{"summary":"\"อัตลักษณ์\" หมายถึง ลักษณะเฉพาะตัวที่โดดเด่นและแตกต่างจากที่อื่นอย่างแท้จริง","steps":["บริบทระบุคำว่า \"ความแตกต่างที่เป็น... อันแท้จริง\"","คำว่า \"อัตลักษณ์\" (Identity) สื่อถึงความเฉพาะตัวและเอกลักษณ์ที่ไม่เหมือนใครได้ตรงที่สุด"],"tip":"อัตลักษณ์ = คุณลักษณะเฉพาะตัว / วัฒนธรรม = วิถีชีวิตที่ถ่ายทอดร่วมกัน"}'::jsonb, NULL, NULL),
(20, 'verbal', 'ความสามารถทางภาษา', 'การเลือกใช้คำศัพท์ทางจิตวิทยาและสังคมศาสตร์', 'คนเรามักจะชอบเข้าไปดูหน้าเพจที่ตนเองกดจองทริปไปเที่ยวอยู่ซ้ำ ๆ ทั้งที่จองเสร็จแล้ว แม้จะเป็นทริปในอีก 5 เดือนข้างหน้าก็ตาม นักจิตวิทยาอธิบาย________นี้ว่าเป็นความฝันที่มีความสุขและเกิดกำลังใจ', '[{"id":1,"text":"ลักษณะ"},{"id":2,"text":"เหตุการณ์"},{"id":3,"text":"พฤติกรรม"},{"id":4,"text":"สถานการณ์"},{"id":5,"text":"ภาวะการณ์"}]'::jsonb, 3, '{"summary":"การกระทำที่เข้าไปดูซ้ำ ๆ จัดเป็นการกระทำที่สังเกตได้ของบุคคล ซึ่งเรียกว่า \"พฤติกรรม\"","steps":["การเข้าไปกดดูซ้ำ ๆ เป็น Action หรือการกระทำของมนุษย์","ในทางจิตวิทยา การกระทำเหล่านี้เรียกว่า \"พฤติกรรม\" (Behavior)"],"tip":"คำว่า \"พฤติกรรม\" มักคู่กับคำว่า \"นักจิตวิทยาอธิบาย...\""}'::jsonb, NULL, NULL),
(21, 'numerical', 'ความสามารถทางตัวเลข', 'อนุกรมมิติ', 'คำชี้แจง: ให้หาตัวเลขถัดไปที่เรียงกันอย่างมีแบบแผน

