(59, 'spatial', 'ความสามารถทางมิติสัมพันธ์', 'แบบประกอบภาพ', 'พิจารณาภาพโจทย์ข้อ 59 ด้านล่าง แล้วเลือกคำตอบที่ถูกต้องที่สุด', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 5, '{"summary":"นำชิ้นส่วนมาประกบตามแนวบล็อกที่เว้าอยู่ ตรงกับตัวเลือกที่ 5","steps":["สังเกตภาพโจทย์และตำแหน่งจุดสังเกตสำคัญ (รอยพับ, ระนาบหมุน, หรือตำแหน่งแถบสี)","เปรียบเทียบกับตัวเลือกทั้ง 5 พบว่าตัวเลือกที่ 5 ถูกต้องตรงตามหลักเรขาคณิตมิติสัมพันธ์"],"tip":"ในข้อสอบมิติสัมพันธ์ ให้จับจุดสังเกตเด่น ๆ 1-2 จุดแล้วตัดช้อยส์ที่ไม่ตรงออกก่อน"}'::jsonb, '/exam_images/q59.png', NULL),
(60, 'spatial', 'ความสามารถทางมิติสัมพันธ์', 'แบบประกอบภาพ', 'พิจารณาภาพโจทย์ข้อ 60 ด้านล่าง แล้วเลือกคำตอบที่ถูกต้องที่สุด', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 2, '{"summary":"ชิ้นส่วนตัวเลือกที่ 2 เข้าล็อคกับชิ้นส่วนหลักตรงตามตำแหน่งแถบสี","steps":["สังเกตภาพโจทย์และตำแหน่งจุดสังเกตสำคัญ (รอยพับ, ระนาบหมุน, หรือตำแหน่งแถบสี)","เปรียบเทียบกับตัวเลือกทั้ง 5 พบว่าตัวเลือกที่ 2 ถูกต้องตรงตามหลักเรขาคณิตมิติสัมพันธ์"],"tip":"ในข้อสอบมิติสัมพันธ์ ให้จับจุดสังเกตเด่น ๆ 1-2 จุดแล้วตัดช้อยส์ที่ไม่ตรงออกก่อน"}'::jsonb, '/exam_images/q60.png', NULL),
(61, 'logical', 'ความสามารถทางเหตุผล', 'อนุกรมภาพ', 'พิจารณาภาพโจทย์ข้อ 61 ด้านล่าง แล้วเลือกคำตอบที่ถูกต้องที่สุดตามลำดับอนุกรมภาพ', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 3, '{"summary":"การเคลื่อนที่และการเปลี่ยนแปลงของเครื่องหมายบวกและแถบสีตรงกับตัวเลือกที่ 3","steps":["สังเกตการหมุนและการเปลี่ยนตำแหน่งของสัญลักษณ์ในแต่ละช่องตามเข็มนาฬิกา","ตัวเลือกที่ 3 มีตำแหน่งแถบสีและเครื่องหมายบวกสอดคล้องตามอนุกรม"],"tip":"สังเกตทีละองค์ประกอบ (เช่น ทิศทาง และจำนวน) เพื่อตัดช้อยส์"}'::jsonb, '/exam_images/q61.png', NULL),
(62, 'logical', 'ความสามารถทางเหตุผล', 'อนุกรมภาพ', 'พิจารณาภาพโจทย์ข้อ 62 ด้านล่าง แล้วเลือกคำตอบที่ถูกต้องที่สุดตามลำดับอนุกรมภาพ', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 3, '{"summary":"การเปลี่ยนทิศทางของตัว U และสัญลักษณ์เส้นตรงเป็นลำดับต่อเนื่องตรงกับตัวเลือกที่ 3","steps":["แกนของตัว U หมุนทีละ 90 องศา และสลับข้างเส้นประ","ช่องถัดไปต้องชี้ลงด้านล่างและเส้นทึบอยู่ทางขวา ตรงกับตัวเลือกที่ 3"],"tip":"หาองศาการหมุนของภาพทีละขั้น"}'::jsonb, '/exam_images/q62.png', NULL),
(63, 'logical', 'ความสามารถทางเหตุผล', 'อนุกรมภาพ', 'พิจารณาภาพโจทย์ข้อ 63 ด้านล่าง แล้วเลือกคำตอบที่ถูกต้องที่สุดตามลำดับอนุกรมภาพ', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 1, '{"summary":"การหมุนตามเข็มนาฬิกาของจุดดำและจุดขาวในรูปหกเหลี่ยมตรงกับตัวเลือกที่ 1","steps":["จุดดำเดินหน้า 1 ช่องตามเข็มนาฬิกา และจุดขาวข้ามทีละ 2 ช่องทวนเข็ม","ตำแหน่งถัดไปของทั้งสองจุดมาบรรจบตามตัวเลือกที่ 1"],"tip":"นับจำนวนก้าวของจุดดำและจุดขาวแยกกัน"}'::jsonb, '/exam_images/q63.png', NULL),
(64, 'logical', 'ความสามารถทางเหตุผล', 'อนุกรมภาพ', 'พิจารณาภาพโจทย์ข้อ 64 ด้านล่าง แล้วเลือกคำตอบที่ถูกต้องที่สุดตามลำดับอนุกรมภาพ', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 2, '{"summary":"จำนวนและทิศทางการยื่นออกของบล็อกเพิ่มขึ้นตามลำดับในตัวเลือกที่ 2","steps":["นับจำนวนบล็อกและสังเกตส่วนที่ต่อขยายเพิ่มขึ้นทีละ 1 ด้าน","ภาพที่ต้องการต้องมีการขยายบล็อกทางด้านล่างซ้ายตรงกับตัวเลือกที่ 2"],"tip":"นับผลรวมของบล็อกและทิศทางการงอก"}'::jsonb, '/exam_images/q64.png', NULL),
(65, 'logical', 'ความสามารถทางเหตุผล', 'อนุกรมภาพ', 'พิจารณาภาพโจทย์ข้อ 65 ด้านล่าง แล้วเลือกคำตอบที่ถูกต้องที่สุดตามลำดับอนุกรมภาพ', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 5, '{"summary":"สามเหลี่ยมสีดำเคลื่อนที่และหมุนตามลำดับอนุกรม ตรงกับตัวเลือกที่ 5","steps":["มุมยอดของสามเหลี่ยมหมุนสลับ 45 องศา และเคลื่อนรอบมุมทั้งสี่","ตำแหน่งสุดท้ายต้องอยู่ที่มุมล่างขวาพร้อมหันยอดขึ้นบน ตรงกับตัวเลือกที่ 5"],"tip":"สังเกตทิศทางมุมแหลมของสามเหลี่ยม"}'::jsonb, '/exam_images/q65.png', NULL),
(66, 'logical', 'ความสามารถทางเหตุผล', 'ความสัมพันธ์ของภาพ', 'พิจารณาภาพโจทย์ข้อ 66 ด้านล่าง แล้วเลือกคำตอบที่มีความสัมพันธ์สอดคล้องกับภาพคู่แรก', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 5, '{"summary":"ความสัมพันธ์แบบตัดซ้อน/ซ้อนทับในคู่แรก สอดคล้องกับคู่ในตัวเลือกที่ 5","steps":["คู่แรกเป็นการดึงรูปทรงภายในออกมาขยายขนาดและสลับสีพื้นหลัง","ใช้กฎเดียวกันกับคู่ที่สอง จะได้ผลลัพธ์ตรงกับตัวเลือกที่ 5"],"tip":"เขียนกฎของคู่แรกเป็นคำพูดสั้น ๆ แล้วนำไปใช้กับคู่ที่สอง"}'::jsonb, '/exam_images/q66.png', NULL),
(67, 'logical', 'ความสามารถทางเหตุผล', 'ความสัมพันธ์ของภาพ', 'พิจารณาภาพโจทย์ข้อ 67 ด้านล่าง แล้วเลือกคำตอบที่มีความสัมพันธ์สอดคล้องกับภาพคู่แรก', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 3, '{"summary":"รูปสามเหลี่ยมกลับด้านประกบกัน สอดคล้องกับรูปทรงในตัวเลือกที่ 3","steps":["คู่แรกนำรูปต้นฉบับมาสะท้อนตามแนวดิ่งและซ้อนจุดกึ่งกลาง","เมื่อสะท้อนภาพที่สองตามแนวเดียวกันจะได้ตรงกับตัวเลือกที่ 3"],"tip":"หาแกนสมมาตรที่ใช้แปลงภาพคู่แรก"}'::jsonb, '/exam_images/q67.png', NULL),
(68, 'logical', 'ความสามารถทางเหตุผล', 'ความสัมพันธ์ของภาพ', 'พิจารณาภาพโจทย์ข้อ 68 ด้านล่าง แล้วเลือกคำตอบที่มีความสัมพันธ์สอดคล้องกับภาพคู่แรก', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 4, '{"summary":"การแปลงรูปทรงด้านในและกรอบนอกตรงกับตัวเลือกที่ 4","steps":["รูปทรงด้านนอกลดจำนวนเหลี่ยมลง 1 และเส้นด้านในเพิ่มขึ้น 1 เส้น","จากห้าเหลี่ยมลดเหลือสี่เหลี่ยม และเส้นด้านในเพิ่มจาก 2 เป็น 3 เส้น ตรงกับตัวเลือกที่ 4"],"tip":"นับจำนวนเหลี่ยมและจำนวนเส้นด้านใน"}'::jsonb, '/exam_images/q68.png', NULL),
(69, 'logical', 'ความสามารถทางเหตุผล', 'ความสัมพันธ์ของภาพ', 'พิจารณาภาพโจทย์ข้อ 69 ด้านล่าง แล้วเลือกคำตอบที่มีความสัมพันธ์สอดคล้องกับภาพคู่แรก', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 4, '{"summary":"ความสัมพันธ์ของแถบเส้นและรอยหยักตรงกับตัวเลือกที่ 4","steps":["สังเกตรอยหยักกลับทิศ 180 องศา และแถบสีขาวดำสลับกัน","แปลงคู่ที่สองในลักษณะเดียวกันตรงกับตัวเลือกที่ 4"],"tip":"สังเกตการสลับสีขาว-ดำ (Invert)"}'::jsonb, '/exam_images/q69.png', NULL),
(70, 'logical', 'ความสามารถทางเหตุผล', 'ความสัมพันธ์ของภาพ', 'พิจารณาภาพโจทย์ข้อ 70 ด้านล่าง แล้วเลือกคำตอบที่มีความสัมพันธ์สอดคล้องกับภาพคู่แรก', '[{"id":1,"text":"ตัวเลือกที่ 1"},{"id":2,"text":"ตัวเลือกที่ 2"},{"id":3,"text":"ตัวเลือกที่ 3"},{"id":4,"text":"ตัวเลือกที่ 4"},{"id":5,"text":"ตัวเลือกที่ 5"}]'::jsonb, 5, '{"summary":"การหมุน 90 องศาและการสลับตำแหน่งแรเงาสอดคล้องกับตัวเลือกที่ 5","steps":["หมุนรูปตามเข็ม 90 องศา และย้ายช่องแรเงาไปยังช่องตรงข้าม","กระทำแบบเดียวกันกับภาพคู่ที่สอง ได้ผลตรงกับตัวเลือกที่ 5"],"tip":"ตรวจสอบทิศทางการหมุนและการย้ายแรเงา"}'::jsonb, '/exam_images/q70.png', NULL),
(71, 'logical', 'ความสามารถทางเหตุผล', 'การวิเคราะห์เงื่อนไขสัญลักษณ์และข้อความ', 'คำชี้แจงข้อ 71 - 75: ให้พิจารณาข้อความและข้อสรุปที่เกี่ยวข้องกับความสัมพันธ์ที่กำหนดให้ แล้วพิจารณาว่าข้อสรุป ก, ข หรือ ค ข้อใดบ้างที่ถูกต้องตามเหตุผล

สถานการณ์:
A, B และ C เลือกคณะและมหาวิทยาลัยเพื่อสมัคร TCAS ดังนี้
• A และ B เลือกคณะวิทยาศาสตร์
• B และ C เลือกมหาวิทยาลัยเดียวกัน
• A และ C เลือกมหาวิทยาลัยเอกชน

พิจารณาข้อสรุปต่อไปนี้:
(ก) A และ C เลือกคณะเดียวกัน
(ข) A และ B เลือกมหาวิทยาลัยเอกชน
(ค) ทั้งสามคนเลือกมหาวิทยาลัยเดียวกัน

ข้อสรุปใดถูกต้อง', '[{"id":1,"text":"ข้อ ก. ข้อเดียว"},{"id":2,"text":"ข้อ ข. ข้อเดียว"},{"id":3,"text":"ข้อ ค. ข้อเดียว"},{"id":4,"text":"ข้อ ก. และ ข."},{"id":5,"text":"ข้อ ข. และ ค."}]'::jsonb, 2, '{"summary":"ข้อ ข. ถูกต้องเพียงข้อเดียว เพราะ C เลือก ม.เอกชน และ B กับ C เลือก ม. เดียวกัน ดังนั้น B จึงเลือก ม.เอกชนด้วย เช่นเดียวกับ A ที่เลือก ม.เอกชน","steps":["A และ C เลือก ม.เอกชน -> ทั้ง A และ C อยู่ ม.เอกชน","B และ C เลือก ม.เดียวกัน -> ในเมื่อ C อยู่ ม.เอกชน B ก็ต้องอยู่ ม.เอกชนด้วย","สรุปได้ว่าทั้ง A และ B เลือกมหาวิทยาลัยเอกชน (ข้อ ข. ถูก)","ข้อ ก: โจทย์ไม่ได้ระบุคณะของ C จึงสรุปไม่ได้ว่า A และ C คณะเดียวกัน","ข้อ ค: B และ C ม.เดียวกัน, A และ C อยู่ ม.เอกชน แต่อาจเป็นคนละมหาวิทยาลัยเอกชนกันได้"],"tip":"ไล่เรียงเงื่อนไขที่เชื่อมโยงกันทีละเปลาะ และไม่ด่วนสรุปเกินกว่าที่โจทย์ระบุ"}'::jsonb, NULL, NULL),
(72, 'logical', 'ความสามารถทางเหตุผล', 'การวิเคราะห์ลำดับและเงื่อนไข', 'สถานการณ์:
ตี่ หมวย อ้วน และน้อย เข้าคิวสั่งเครื่องดื่ม 3 เมนู คือ กาแฟ ชา และโกโก้ แต่ละคนเลือกเพียงเมนูเดียว
• มีลูกค้าสั่งโกโก้เพียงคนเดียว
• ตี่และหมวยสั่งเครื่องดื่มชนิดเดียวกัน
• ลูกค้าที่สั่งกาแฟอยู่ในลำดับต่อจากลูกค้าที่สั่งโกโก้เท่านั้น

พิจารณาข้อสรุปต่อไปนี้:
(ก) ตี่สั่งชา
(ข) อ้วนสั่งโกโก้
(ค) น้อยสั่งกาแฟ

ข้อสรุปใดถูกต้อง', '[{"id":1,"text":"ข้อ ก. ข้อเดียว"},{"id":2,"text":"ข้อ ข. ข้อเดียว"},{"id":3,"text":"ข้อ ค. ข้อเดียว"},{"id":4,"text":"ข้อ ก. และ ข."},{"id":5,"text":"ข้อ ข. และ ค."}]'::jsonb, 1, '{"summary":"ตี่และหมวยสั่งเครื่องดื่มชนิดเดียวกัน ไม่ใช่โกโก้ (เพราะมีคนเดียว) และไม่ใช่กาแฟ (เพราะกาแฟต่อจากโกโก้เท่านั้น) ตี่จึงต้องสั่งชา","steps":["โกโก้มีคนสั่งแค่ 1 คน -> ตี่กับหมวยสั่งเหมือนกันจึงสั่งโกโก้ไม่ได้","คนสั่งกาแฟต้องต่อจากคนสั่งโกโก้เท่านั้น หมายความว่ามีคนสั่งกาแฟได้เพียง 1 คน (คนที่ต่อจากคนสั่งโกโก้)","ดังนั้น ตี่และหมวยจึงสั่งกาแฟพร้อมกันไม่ได้ เมนูเดียวที่ตี่และหมวยสั่งได้คือ \"ชา\"","ดังนั้น ข้อสรุป (ก) ตี่สั่งชา จึงถูกต้องแน่นอน"],"tip":"ใช้เงื่อนไขข้อจำกัดจำนวนคนตัดเมนูที่เป็นไปไม่ได้ออก"}'::jsonb, NULL, NULL),
(73, 'logical', 'ความสามารถทางเหตุผล', 'การจัดตำแหน่งรอบโต๊ะกลม', 'สถานการณ์:
เจน ปิง โม้ นาย ดาว หวาน ทั้งหกคนนั่งรอบโต๊ะกลมหันหน้าเข้าหากัน
• เจนนั่งติดกับดาวและหวาน และนั่งตรงข้ามกับโม้
• นายไม่ได้นั่งติดกับหวาน

พิจารณาข้อสรุปต่อไปนี้:
(ก) หวานนั่งติดกับปิง
(ข) ดาวนั่งตรงกันข้ามกับปิง
(ค) โม้นั่งอยู่ทางซ้ายมือของนาย

ข้อสรุปใดถูกต้อง', '[{"id":1,"text":"ข้อ ก. ข้อเดียว"},{"id":2,"text":"ข้อ ข. ข้อเดียว"},{"id":3,"text":"ข้อ ค. ข้อเดียว"},{"id":4,"text":"ข้อ ก. และ ข."},{"id":5,"text":"ข้อ ข. และ ค."}]'::jsonb, 4, '{"summary":"การจัดผังรอบโต๊ะกลมได้ลำดับ: เจน ติดกับ (ดาว, หวาน), ตรงข้ามโม้, นายติดดาว, ปิงติดหวาน ทำให้ข้อ (ก) และ (ข) ถูกต้อง","steps":["เจนอยู่ตรงข้ามโม้ ขนาบข้างด้วยดาวและหวาน","เหลืออีก 2 คนคือนายกับปิง โดยนายไม่ติดหวาน แสดงว่านายต้องติดดาว","ดังนั้น ปิงจึงต้องติดหวาน (ข้อ ก. ถูก)","เมื่อนายติดดาว และปิงติดหวาน จะได้ว่าดาวอยู่ตรงข้ามกับปิง (ข้อ ข. ถูก)","ดังนั้น ข้อสรุปที่ถูกต้องคือ ข้อ ก. และ ข."],"tip":"วาดวงกลม 6 ช่องแล้วลงตำแหน่งคนที่นั่งตรงข้ามกันก่อนเป็นหลัก"}'::jsonb, NULL, NULL),
(74, 'logical', 'ความสามารถทางเหตุผล', 'การเปรียบเทียบเชิงตรรกะและอสมการ', 'สถานการณ์:
ร้านค้าตั้งราคาขายตุ๊กตาตัวละครชุดวันพีช จำนวน 8 ตัว ประกอบไปด้วย ลูฟี่ 3 ตัว, โซโร 3 ตัว และซันจิ 2 ตัว แต่ละตัวมีราคาไม่เท่ากัน ดังนี้
• ลูฟี่ 2 ตัว ราคารวมกันแพงกว่าราคารวมกันของซันจิ 2 ตัว
• ลูฟี่ 3 ตัว ราคารวมกันเท่ากับราคารวมกันของโซโร 3 ตัว
• มีลูฟี่อยู่ 1 ตัว ที่มีราคาเท่ากับราคารวมกันของโซโร 2 ตัว

พิจารณาข้อสรุปต่อไปนี้:
(ก) ซันจิ 2 ตัว ราคารวมกันแพงกว่าลูฟี่ 1 ตัว
(ข) มีโซโร 1 ตัว ที่มีราคาเท่ากับราคารวมกันของลูฟี่ 2 ตัว
(ค) มีโซโร 2 ตัว มีราคาแพงกว่าราคารวมกันของซันจิ 2 ตัว

ข้อสรุปใดถูกต้อง', '[{"id":1,"text":"ข้อ ก. ข้อเดียว"},{"id":2,"text":"ข้อ ข. ข้อเดียว"},{"id":3,"text":"ข้อ ค. ข้อเดียว"},{"id":4,"text":"ข้อ ก. และ ข."},{"id":5,"text":"ข้อ ข. และ ค."}]'::jsonb, 2, '{"summary":"จากผลรวมลูฟี่ 3 ตัวเท่ากับโซโร 3 ตัว แต่มีลูฟี่ตัวหนึ่งแพงเท่ากับโซโร 2 ตัว ส่งผลให้โซโรที่เหลือตัวหนึ่งต้องมีราคาเท่ากับลูฟี่ 2 ตัวที่เหลือเพื่อดุลสมการ (ข้อ ข. ถูกข้อเดียว)","steps":["L1 + L2 + L3 = Z1 + Z2 + Z3","กำหนดให้ L1 = Z1 + Z2","แทนค่า: (Z1 + Z2) + L2 + L3 = Z1 + Z2 + Z3 -> L2 + L3 = Z3","นั่นคือ มีโซโร 1 ตัว (Z3) มีราคาเท่ากับราคารวมกันของลูฟี่ 2 ตัว (L2 + L3) เสมอ (ข้อ ข. ถูกต้องแน่นอน)"],"tip":"ใช้การแทนค่าตัวแปรในสมการพีชคณิตเพื่อพิสูจน์ข้อสรุป"}'::jsonb, NULL, NULL),
(75, 'logical', 'ความสามารถทางเหตุผล', 'การจัดกลุ่มแบบมีเงื่อนไข', 'สถานการณ์:
A, B, C, D, E, F, G, H, J ทั้งเก้าคน แบ่งออกเป็น 3 กลุ่ม กลุ่มละ 3 คน
• A และ F อยู่กลุ่มเดียวกัน
• C, D, G อยู่คนละกลุ่ม
• D ไม่ได้อยู่กลุ่มเดียวกันกับ A, B และ H

พิจารณาข้อสรุปต่อไปนี้:
(ก) B และ G อยู่กลุ่มเดียวกัน
(ข) C และ F อยู่กลุ่มเดียวกัน
(ค) E และ J อยู่กลุ่มเดียวกัน

ข้อสรุปใดถูกต้อง', '[{"id":1,"text":"ข้อ ก. ข้อเดียว"},{"id":2,"text":"ข้อ ข. ข้อเดียว"},{"id":3,"text":"ข้อ ค. ข้อเดียว"},{"id":4,"text":"ข้อ ก. และ ข."},{"id":5,"text":"ข้อ ก. และ ค."}]'::jsonb, 3, '{"summary":"จากการจัดกลุ่มตามเงื่อนไข D ไม่สามารถอยู่กับ A, F, B, H, C, G ได้ จึงต้องอยู่กับคนที่เหลือคือ E และ J ทำให้ E และ J ต้องอยู่กลุ่มเดียวกันเสมอ","steps":["กลุ่มที่มี D: D ห้ามอยู่กับ C, G (คนละกลุ่ม), ห้ามอยู่กับ A, B, H","และกลุ่มของ A มี F อยู่ด้วยแล้ว (A, F)","ดังนั้น คนที่สามารถอยู่กลุ่มเดียวกับ D ได้มีเพียง E และ J เท่านั้น","ทำให้กลุ่มของ D ต้องเป็น {D, E, J}","ข้อสรุป (ค) E และ J อยู่กลุ่มเดียวกัน จึงถูกต้องแน่นอน 100%"],"tip":"ตัดคนที่ถูกห้ามไม่ให้อยู่ร่วมกลุ่มออก คนที่เหลือจะถูกบีบให้อยู่ในกลุ่มนั้น"}'::jsonb, NULL, NULL),
(76, 'logical', 'ความสามารถทางเหตุผล', 'การวิเคราะห์เงื่อนไขสถานการณ์', 'คำชี้แจงข้อ 76 - 80: ให้พิจารณาสถานการณ์ที่กำหนด
• ตอบ 1 เมื่อข้อสรุปทั้ง ก. และ ข. ถูก
• ตอบ 2 เมื่อข้อสรุปทั้ง ก. และ ข. ผิด
• ตอบ 3 เมื่อข้อสรุปทั้ง ก. และ ข. ไม่สามารถสรุปได้แน่ชัด
• ตอบ 4 เมื่อข้อสรุป ก. ถูก ส่วนข้อสรุป ข. ผิดหรือไม่แน่ชัด
• ตอบ 5 เมื่อข้อสรุป ข. ถูก ส่วนข้อสรุป ก. ผิดหรือไม่แน่ชัด

สถานการณ์:
นักเรียน ม.6 จำนวน 7 คน (ก้อย, เต่า, โจ้, แนน, ทอย, โอม, มิว) เข้าสอบดนตรีสากล (กีตาร์, เปียโน, แซกโซโฟน, ไวโอลิน)
• มีเครื่องดนตรี 1 ชนิดที่มีผู้เลือก 3 คน
• เปียโนมีผู้เลือก 2 คน โดยทั้งสองคนสอบต่อจากผู้สอบที่เลือกไวโอลิน
• เต่าเข้าสอบเป็นคนสุดท้าย และเลือกเครื่องดนตรีชนิดเดียวกับโจ้
• ผู้สอบลำดับที่ 2 เลือกเครื่องดนตรีที่มีผู้เลือกคนเดียว
• โจ้สอบเป็นลำดับที่ 4 ต่อจากมิว
• โอมเลือกกีตาร์ และสอบหลังจากโจ้สอบแล้ว

ข้อ 76:
(ก) มิวเลือกไวโอลิน
(ข) เต่าเลือกเปียโน', '[{"id":1,"text":"ข้อสรุปทั้ง ก. และ ข. ถูก"},{"id":2,"text":"ข้อสรุปทั้ง ก. และ ข. ผิด"},{"id":3,"text":"ข้อสรุปทั้ง ก. และ ข. ไม่สามารถสรุปได้แน่ชัด"},{"id":4,"text":"ข้อสรุป ก. ถูก ส่วนข้อสรุป ข. ผิดหรือไม่แน่ชัด"},{"id":5,"text":"ข้อสรุป ข. ถูก ส่วนข้อสรุป ก. ผิดหรือไม่แน่ชัด"}]'::jsonb, 1, '{"summary":"จากการจัดลำดับ โจ้ลำดับที่ 4 สอบเปียโนต่อจากมิวลำดับที่ 3 ซึ่งเลือกไวโอลิน และเต่าลำดับที่ 7 เลือกเครื่องเดียวกับโจ้คือเปียโน ทั้ง ก และ ข จึงถูกต้อง","steps":["โจ้สอบลำดับ 4 ต่อจากมิว (มิวสอบลำดับ 3)","เปียโนมี 2 คน และต้องสอบต่อจากคนสอบไวโอลิน แสดงว่าลำดับ 4 (โจ้) ต้องสอบเปียโน และมิวลำดับ 3 สอบไวโอลิน (ก. ถูก)","เต่าสอบคนสุดท้าย (ลำดับ 7) เลือกเครื่องเดียวกับโจ้ จึงเลือกเปียโน (ข. ถูก)","ดังนั้น ข้อสรุปทั้ง ก. และ ข. ถูก"],"tip":"เขียนตารางลำดับ 1 ถึง 7 แล้วนำเงื่อนไข \"เปียโนต่อจากไวโอลิน\" มาจับคู่กับลำดับ 3 และ 4"}'::jsonb, NULL, NULL),
(77, 'logical', 'ความสามารถทางเหตุผล', 'การวิเคราะห์เงื่อนไขสถานการณ์', 'สถานการณ์เดิม (ข้อ 76-80):

ข้อ 77:
(ก) ผู้สอบลำดับที่ 2 เลือกแซกโซโฟน
(ข) ผู้สอบลำดับที่ 5 เลือกกีตาร์', '[{"id":1,"text":"ข้อสรุปทั้ง ก. และ ข. ถูก"},{"id":2,"text":"ข้อสรุปทั้ง ก. และ ข. ผิด"},{"id":3,"text":"ข้อสรุปทั้ง ก. และ ข. ไม่สามารถสรุปได้แน่ชัด"},{"id":4,"text":"ข้อสรุป ก. ถูก ส่วนข้อสรุป ข. ผิดหรือไม่แน่ชัด"},{"id":5,"text":"ข้อสรุป ข. ถูก ส่วนข้อสรุป ก. ผิดหรือไม่แน่ชัด"}]'::jsonb, 1, '{"summary":"ลำดับที่ 2 มีคนเลือกเครื่องดนตรีชนิดเดียวคือแซกโซโฟน และโอมสอบต่อจากโจ้ (ลำดับ 5) เลือกกีตาร์ ทั้ง ก และ ข ถูกต้อง","steps":["เครื่องดนตรีที่มีคนเลือก 1 คนคือ แซกโซโฟน (เพราะเปียโนมี 2, ไวโอลินมี 2 หรือ 3, กีตาร์มี 2 หรือ 3)","ผู้สอบลำดับที่ 2 จึงเลือกแซกโซโฟน (ก. ถูก)","โอมเลือกกีตาร์และสอบหลังโจ้ (ลำดับ 5) คือกีตาร์ (ข. ถูก)","ดังนั้น ข้อสรุปทั้ง ก. และ ข. ถูก"],"tip":"ตรวจสอบจำนวนผู้เลือกเครื่องดนตรีแต่ละชนิด เปียโน=2 แซกโซโฟน=1"}'::jsonb, NULL, NULL),
(78, 'logical', 'ความสามารถทางเหตุผล', 'การวิเคราะห์เงื่อนไขสถานการณ์', 'สถานการณ์เดิม (ข้อ 76-80):

